/* From Uiverse.io by Custyyyy - Tags: button */
.__UIV_SCOPE__ #bottone1 {
 padding-left: 33px;
 padding-right: 33px;
 padding-bottom: 16px;
 padding-top: 16px;
 border-radius: 9px;
 background: #d5f365;
 border: none;
 font-family: inherit;
 text-align: center;
 cursor: pointer;
 transition: 0.4s;
}

.__UIV_SCOPE__ #bottone1:hover {
 box-shadow: 7px 5px 56px -14px #C3D900;
}

.__UIV_SCOPE__ #bottone1:active {
 transform: scale(0.97);
 box-shadow: 7px 5px 56px -10px #C3D900;
}
